if(page<2){const char*labels[2][3]={{"Pacote PKG","Pasta de destino","EXTRAIR"},{"PKG package","Destination folder","EXTRACT"}};for(int i=0;i<3;i++){int y=288+i*151;rect(365,y,1495,116,color(20,34,53));border(365,y,1495,116,focus&&row==i?accent():color(45,66,92));text(391,y+13,labels[english][i],1,color(174,201,223));text(391,y+57,i==0?(source[0]?source:"Selecionar ficheiro .pkg..."):i==1?destination:"Motor de extracao ainda nao integrado",1,color(236,244,252));}text(380,816,status,1,color(163,193,213));text(380,867,"Esta etapa valida a interface. Nao extrai nem instala PKG.",1,color(245,194,121));}
