int ui_input(uint32_t b){if(!b)return 0;if(exit_dialog){if(b&BTN_CROSS)quit=1;if(b&BTN_CIRCLE)exit_dialog=0;return 1;}if(picker){if(b&BTN_L1){picker=0;return 1;}if(b&BTN_OPTIONS){if(picker_dest){snprintf(destination,sizeof(destination),"%s",directory);picker=0;}return 1;}if(b&BTN_CIRCLE){parent();return 1;}if(b&BTN_UP){if(entry_selected>0)entry_selected--;return 1;}if(b&BTN_DOWN){if(entry_selected+1<entry_count)entry_selected++;return 1;}if((b&BTN_CROSS)&&entry_count){char next[1024];int n=snprintf(next,sizeof(next),"%s%s%s",directory,!strcmp(directory,"/")?"":"/",names[entry_selected]);if(n<0||n>=(int)sizeof(next)){snprintf(status,sizeof(status),"Caminho demasiado longo.");return 1;}if(dirs[entry_selected]){strcpy(directory,next);scan();}else{strcpy(source,next);picker=0;}return 1;}return 0;}
if(b&BTN_OPTIONS){exit_dialog=1;return 1;}if(b&BTN_R1){page=(page+1)%4;row=0;return 1;}if(b&BTN_L1){page=(page+3)%4;row=0;return 1;}if(b&BTN_LEFT||b&BTN_CIRCLE){focus=0;return 1;}if(b&BTN_RIGHT){focus=1;return 1;}if(b&BTN_UP){if(focus){if(row>0)row--;}else page=(page+3)%4;return 1;}if(b&BTN_DOWN){if(focus){if(row<2)row++;}else page=(page+1)%4;return 1;}if(b&BTN_CROSS){if(!focus){focus=1;return 1;}if(page<2){if(row<2){picker=1;picker_dest=row==1;strcpy(directory,"/mnt");scan();}else snprintf(status,sizeof(status),"Extracao indisponivel nesta versao de interface.");}else if(page==2){if(row==0)english=!english;else if(row==1)theme=(theme+1)%3;else{mkdir("/data/arctic_native",0755);FILE*f=fopen("/data/arctic_native/settings.txt","w");if(f){fprintf(f,"%d %d\n",english,theme);fclose(f);snprintf(status,sizeof(status),"Definicoes guardadas.");}else snprintf(status,sizeof(status),"Nao foi possivel guardar as definicoes.");}}return 1;}return 0;}
